-- Run migration in the surrounding transaction before this evidence; rollback all fixtures.
SELECT set_config('request.jwt.claim.sub','893c58dd-420b-4dfa-aff7-844e20e634c5',true);
CREATE TEMP TABLE dataset_intake_proof(check_name text PRIMARY KEY,passed boolean NOT NULL) ON COMMIT DROP;
DO $test$
DECLARE a jsonb;b jsonb;first_batch jsonb;second_batch jsonb;r jsonb;req uuid:=gen_random_uuid();rows_json jsonb;bad boolean;before_old bigint;before_tx bigint;worker_id uuid;
BEGIN
 SELECT count(*) INTO before_old FROM public.rr_import_batches_test71;
 SELECT count(*) INTO before_tx FROM public.rr_account_transactions_v805;
 a:=public.rr_source_dataset_create_test71(req,'ROLLBACK DATASET A');
 b:=public.rr_source_dataset_create_test71(gen_random_uuid(),'ROLLBACK DATASET B');
 IF a->>'dataset_id'=b->>'dataset_id' THEN RAISE EXCEPTION 'Datasets collide';END IF;
 IF public.rr_source_dataset_create_test71(req,'ROLLBACK DATASET A')->>'dataset_id'<>a->>'dataset_id' THEN RAISE EXCEPTION 'Dataset retry duplicated';END IF;
 INSERT INTO dataset_intake_proof VALUES('dataset_creation_retry',true);
 bad:=false;BEGIN PERFORM public.rr_source_dataset_create_test71(req,'different');EXCEPTION WHEN others THEN bad:=SQLERRM LIKE '%different name%';END;IF NOT bad THEN RAISE EXCEPTION 'Dataset conflict accepted';END IF;
 INSERT INTO dataset_intake_proof VALUES('dataset_name_conflict',true);
 bad:=false;BEGIN PERFORM public.rr_dataset_import_stage_test71(NULL,gen_random_uuid(),'source',repeat('a',64),'[{}]');EXCEPTION WHEN others THEN bad:=SQLERRM LIKE '%Draft TEST dataset%';END;IF NOT bad THEN RAISE EXCEPTION 'Null dataset accepted';END IF;
 bad:=false;BEGIN PERFORM public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,gen_random_uuid(),NULL,repeat('a',64),'[{}]');EXCEPTION WHEN others THEN bad:=SQLERRM LIKE '%source reference%';END;IF NOT bad THEN RAISE EXCEPTION 'Null source accepted';END IF;
 INSERT INTO dataset_intake_proof VALUES('null_dataset_and_source_denied',true);
 rows_json:='[{"module":"LEDGERS","source_key":"cash","record_date":"2026-10-01","evidence_status":"KNOWN","values":{},"references":[]},{"module":"OPENING_GL","source_key":"dr","record_date":"2026-10-01","evidence_status":"KNOWN","values":{"ledger_key":"cash","debit":120,"credit":0},"references":[{"module":"LEDGERS","source_key":"cash"}]},{"module":"OPENING_GL","source_key":"cr","record_date":"2026-10-01","evidence_status":"KNOWN","values":{"ledger_key":"equity","debit":0,"credit":120},"references":[]},{"module":"OPENING_STOCK","source_key":"stock","record_date":"2026-10-01","evidence_status":"KNOWN","values":{"item_key":"review-only","unit":"PCS","quantity":4,"value":120},"references":[]}]';
 first_batch:=public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,req,'ROLLBACK-SOURCE',repeat('a',64),rows_json);
 second_batch:=public.rr_dataset_import_stage_test71((b->>'dataset_id')::uuid,req,'ROLLBACK-SOURCE',repeat('a',64),rows_json);
 IF first_batch->>'batch_id'=second_batch->>'batch_id' THEN RAISE EXCEPTION 'Source crossed datasets';END IF;
 INSERT INTO dataset_intake_proof VALUES('same_source_isolated_between_datasets',true);
 r:=public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,req,'ROLLBACK-SOURCE',repeat('a',64),rows_json);
 IF (r->>'already_staged')::boolean IS DISTINCT FROM true OR r->>'batch_id'<>first_batch->>'batch_id' THEN RAISE EXCEPTION 'Batch retry failed';END IF;
 INSERT INTO dataset_intake_proof VALUES('identical_payload_retry',true);
 bad:=false;BEGIN PERFORM public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,req,'ROLLBACK-SOURCE',repeat('a',64),'[]');EXCEPTION WHEN others THEN bad:=true;END;IF NOT bad THEN RAISE EXCEPTION 'Invalid retry accepted';END IF;
 bad:=false;BEGIN PERFORM public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,req,'ROLLBACK-SOURCE',repeat('a',64),jsonb_set(rows_json,'{1,values,debit}','121'));EXCEPTION WHEN others THEN bad:=SQLERRM LIKE '%different payload%';END;IF NOT bad THEN RAISE EXCEPTION 'Payload conflict accepted';END IF;
 INSERT INTO dataset_intake_proof VALUES('changed_payload_conflict',true);
 bad:=false;BEGIN PERFORM public.rr_dataset_import_report_test71((a->>'dataset_id')::uuid,(second_batch->>'batch_id')::uuid);EXCEPTION WHEN others THEN bad:=SQLERRM LIKE '%does not belong%';END;IF NOT bad THEN RAISE EXCEPTION 'Cross dataset report accepted';END IF;
 INSERT INTO dataset_intake_proof VALUES('cross_dataset_reader_denied',true);
 IF (first_batch#>>'{source_totals,opening_gl,debit}')::numeric<>120 OR (first_batch#>>'{source_totals,opening_gl,credit}')::numeric<>120 OR jsonb_array_length(first_batch->'rows')<>4 THEN RAISE EXCEPTION 'Scoped totals incorrect';END IF;
 INSERT INTO dataset_intake_proof VALUES('scoped_source_aggregates',true);
 r:=public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,gen_random_uuid(),'ROLLBACK-UNKNOWN',repeat('b',64),'[{"module":"OPENING_GL","source_key":"unknown","record_date":"2026-10-01","evidence_status":"UNKNOWN","values":{"ledger_key":"cash","debit":"bad","credit":"bad"},"references":[]}]');
 IF r->>'status'<>'STAGED_WITH_ERRORS' OR (r#>>'{source_totals,opening_gl,debit}') IS NOT NULL THEN RAISE EXCEPTION 'Unknown became zero';END IF;
 INSERT INTO dataset_intake_proof VALUES('unknown_values_excluded_not_zeroed',true);
 r:=public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,gen_random_uuid(),'ROLLBACK-NAN',repeat('c',64),'[{"module":"OPENING_GL","source_key":"nan","record_date":"2026-10-01","evidence_status":"KNOWN","values":{"ledger_key":"cash","debit":"NaN","credit":0},"references":[]}]');
 IF r->>'status'<>'STAGED_WITH_ERRORS' OR (r#>>'{source_totals,opening_gl,debit}') IS NOT NULL THEN RAISE EXCEPTION 'NaN entered totals';END IF;
 INSERT INTO dataset_intake_proof VALUES('nonfinite_numeric_excluded',true);
 r:=public.rr_dataset_import_stage_test71((a->>'dataset_id')::uuid,gen_random_uuid(),'ROLLBACK-BAD-CONTRACT',repeat('d',64),'[{"module":"OPENING_GL","source_key":null,"record_date":"2026-02-31","evidence_status":"KNOWN","values":{"ledger_key":"cash","debit":1,"credit":0},"references":[{"module":"LEDGERS","source_key":"missing"}]}]');
 IF r->>'status'<>'STAGED_WITH_ERRORS' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'findings') f WHERE f->>'code'='ROW_CONTRACT') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'findings') f WHERE f->>'code'='UNRESOLVED_SOURCE_REFERENCE') THEN RAISE EXCEPTION 'Malformed contract accepted';END IF;
 INSERT INTO dataset_intake_proof VALUES('null_key_invalid_date_and_reference_findings',true);
 IF (first_batch->>'cleared_for_import')::boolean OR (first_batch->>'operational_posting_enabled')::boolean OR (first_batch->>'business_records_posted')::int<>0 THEN RAISE EXCEPTION 'Operational activation present';END IF;
 IF (SELECT count(*) FROM public.rr_import_batches_test71)<>before_old OR (SELECT count(*) FROM public.rr_account_transactions_v805)<>before_tx THEN RAISE EXCEPTION 'Legacy or financial rows changed';END IF;
 INSERT INTO dataset_intake_proof VALUES('legacy_and_operational_unchanged',true);
 SELECT auth_user_id INTO worker_id FROM public.rr_user_profiles WHERE is_active AND upper(role_code)='WORKER' AND auth_user_id IS NOT NULL LIMIT 1;
 IF worker_id IS NULL THEN RAISE EXCEPTION 'Worker denial requires existing worker';END IF;
 PERFORM set_config('request.jwt.claim.sub',worker_id::text,true);
 bad:=false;BEGIN PERFORM public.rr_source_dataset_create_test71(gen_random_uuid(),'DENIED');EXCEPTION WHEN SQLSTATE '42501' THEN bad:=true;END;IF NOT bad THEN RAISE EXCEPTION 'Worker intake permitted';END IF;
 INSERT INTO dataset_intake_proof VALUES('worker_intake_denied',true);
 PERFORM set_config('request.jwt.claim.sub','',true);
 bad:=false;BEGIN PERFORM public.rr_dataset_import_report_test71((a->>'dataset_id')::uuid,(first_batch->>'batch_id')::uuid);EXCEPTION WHEN SQLSTATE '42501' THEN bad:=true;END;IF NOT bad THEN RAISE EXCEPTION 'Anonymous report permitted';END IF;
 INSERT INTO dataset_intake_proof VALUES('anonymous_reader_denied',true);
 IF has_table_privilege('authenticated','public.rr_dataset_import_rows_test71','SELECT') OR has_table_privilege('anon','public.rr_source_datasets_test71','SELECT') THEN RAISE EXCEPTION 'Direct table exposed';END IF;
 INSERT INTO dataset_intake_proof VALUES('direct_table_access_closed',true);
END $test$;
SELECT jsonb_build_object('checks',jsonb_agg(jsonb_build_object('check',check_name,'passed',passed) ORDER BY check_name),'count',count(*),'no_business_rows_committed',true,'browser_auth_evidence',false) result FROM dataset_intake_proof;
